///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_preView
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_preView = async function () {
    const sbmOptions = {
        id: "tx_fn_preView",
        method: "post",
        action: "/DscltrendInfo.do?method=dsclTrendPreView&gubun=null",
        ref: "dma_preViewReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf60001.tx_fn_preView" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_excel
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_excel = async function () {
    try { return await $c.data.downFile("/DscltrendInfo.do?method=dsclTrendExcel&str_dt=", "", ($c.util.getComponent("dma_excelReq") ? $c.util.getComponent("dma_excelReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name scwin.tx_fn_dsclSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_dsclSearch = async function () {
    const sbmOptions = {
        id: "tx_fn_dsclSearch",
        method: "post",
        action: "/DscltrendInfo.do",
        ref: "dma_dsclSearchReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf60001.tx_fn_dsclSearch" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.preView
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.preView = async function () {
    /* sdd-asis-lifecycle:begin fn_preView — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const f = (document.form || { elements: [] });
    (function(){ throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + "/DscltrendInfo.do?method=dsclTrendPreView&rd_gubun=null", unresolved: "nav:" + "/DscltrendInfo.do?method=dsclTrendPreView&rd_gubun=null" }; })();

    f.action = "/DscltrendInfo.do?method=dsclTrendPreView&gubun=null";
    $c.util.getComponent('dma_preViewReq').set('SCREN_PROCES_TP_CD', "01");
    f.target = '';
    f.action = '';
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.excel
 * @author Inswave
 * @date 2026. 09. 29
 * @param str_dt end_dt
 * @returns
 * @hidden N
*/
scwin.excel = async function (str_dt, end_dt) {
    /* sdd-asis-lifecycle:begin fn_excel — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const f = (document.form || { elements: [] });
    f.action = "/DscltrendInfo.do?method=dsclTrendExcel&str_dt=" + str_dt + "&end_dt=" + end_dt;
    $c.util.getComponent('dma_preViewReq').set('SCREN_PROCES_TP_CD', "07");
    await scwin.tx_fn_excel();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.dsclSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.dsclSearch = async function () {
    /* sdd-asis-lifecycle:begin fn_dsclSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const f = (document.form || { elements: [] });
    if ($c.util.getComponent('cal_strDt') != null) {
        if (($c.util.getComponent('cal_strDt').getValue() == null ? '' : String($c.util.getComponent('cal_strDt').getValue())) === '' && $c.util.getComponent('cal_strDt') != null) {
            await $c.win.alert("시작일을 지정해주세요.");
            $c.util.getComponent("cal_strDt").focus();
            return;
        }
    }
    if (($c.util.getComponent('cal_endDt').getValue() == null ? '' : String($c.util.getComponent('cal_endDt').getValue())) === '') {
        await $c.win.alert("종료일을 지정해주세요.");
        $c.util.getComponent("cal_endDt").focus();
        return;
    }
    f.action = "/DscltrendInfo.do";
    $c.util.getComponent('dma_preViewReq').set('SCREN_PROCES_TP_CD', "01");
    $c.util.getComponent('dma_preViewReq').set('method', "dsclTrendView");
    await scwin.tx_fn_dsclSearch();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.periodChange
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.periodChange = function () {
    /* sdd-asis-lifecycle:begin periodChange — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let objValue = "";
    if (($c.util.getComponent('rd_gubun').getValue() === '1')) {
        objValue = "1";
    } else {
        if (($c.util.getComponent('rd_gubun').getValue() === '2')) {
            objValue = "2";
        }
    }
    if (objValue === "1") {
        self.id_period.innerHTML = "<input name='str_dt' type='text' class='input' style='width:120px' value='null'/><a href='javascript:void(0);'><img src='/img/dscltrend/ic_cal.gif' width='20' height='18' align='absmiddle'></a> ~ <input name='end_dt' type='text' class='input' style='width:120px' value='null' /><a href='javascript:void(0);'><img src='/img/dscltrend/ic_cal.gif' width='20' height='18' align='absmiddle'></a>";
    } else {
        self.id_period.innerHTML = "<input name='end_dt' type='text' class='input' style='width:120px' value='null' /><a href='javascript:void(0);'><img src='/img/dscltrend/ic_cal.gif' width='20' height='18' align='absmiddle'></a>";
    }
    /* sdd-asis-lifecycle:end */
};
